const writerId='gc-view-'+Math.random().toString(36).slice(2);
const initial={view:'overview',stage:'brief',source:'all',picked:['supplier'],creatorMode:'post',activity:'产品功能体验',audience:'喜欢原创角色、手办与 3D 打印的创作者，希望把平面角色变成可继续创作的 3D 模型。',country:'US',language:'English',objective:'Register',platforms:['Google','Meta','TikTok'],budgets:{Google:60,Meta:60,TikTok:60},landingMode:'activity',landing:'https://example.com/events/demo-launch',generated:false,codePreview:false,utmPlatform:'Google',execution:'idle',ready:false,tasks:[],iteration:false,uploadName:'',showCodex:true,toast:'',promptVisible:false};
const saved=window.demoHost?.widgetState?.privateContent;
let s={...initial,...(saved&&saved.version===1?saved.state:{}),toast:'',promptVisible:false};
if(!saved?.state?.audienceDefinition)s.view='audiences';
s.budgets={...initial.budgets,...s.budgets};
s={audienceEnabled:false,audienceDefinition:'ever_paid',audienceSource:'export',audiencePurpose:'exclude',audienceStage:'draft',audienceVersion:1,audienceRefund:'unconfirmed',audienceWindow:'all',audienceRefresh:'snapshot',audienceDerivedReady:false,audienceRefreshFailed:false,audienceSyncedPlatforms:[],audienceSuccessSnapshot:null,audienceDefinitionConfirmed:false,...s};
s.copyDrafts=s.copyDrafts||{};s.runHistory=s.runHistory||[];s.version=s.version||1;s.audienceTest=s.audienceTest||'None';s.uploadVersion=s.uploadVersion||0;
s.currentUser=s.currentUser||'Alex';s.draftCreator=s.draftCreator||'Alex';s.strategyDrafts=s.strategyDrafts||{};s.campaignFilter=s.campaignFilter||'all';s.ownerFilter=s.ownerFilter||'all';
s.operation=s.operation||'new-campaign';s.parentCampaign=s.parentCampaign||null;s.groupName=s.groupName||'创意测试组';s.extraGroups=s.extraGroups||[];s.platformFilter=s.platformFilter||'all';s.runObjects=s.runObjects||{};
s.round=s.round||1;s.reportKey=s.reportKey||'current';s.simulatedReports=s.simulatedReports||{};s.iterationAction=s.iterationAction||'';s.iterationAcknowledged=false;
if(!s.reviewUiVersion){s.reviewUiVersion=2;s.view='workbench';s.stage='plan';}
