 st.picked=(st.picked||[]).map(x=>mapping[x]||x);if(isFresh)st.picked=['SUP-001@1','SUP-002@1'];
 if(['partial','recovered'].includes(st.execution)){st.runHistory=[...(st.runHistory||[]),{version:st.version,result:st.execution,platforms:(st.resultPlatforms||st.platforms).slice(),ids:{...st.runIds},objects:{...st.runObjects},snapshot:st.runSnapshot||null,executors:{...st.runExecutors},legacyAssets:true}];st.version++;st.runSnapshot=null;st.runObjects={};st.runIds={};st.runExecutors={};st.resultFingerprint='';st.enableIntent=null;st.execution='idle';}
 st.generated=false;st.review=null;st.ready=false;st.creatorMode=st.creatorMode||'file';st.originalPostExample='';st.assetUiVersion=2;st.view='assets';st.stage='prepare';
