function initDestination(st){if(st.destinationUiVersion===1)return;st.destinationUiVersion=1;st.destinationChoice=st.operation==='new-group'?'existing':'new';st.destinationCandidate=st.parentCampaign?.key||'';st.destinationPlatform=st.parentCampaign?.platform||(st.platforms?.length===1?st.platforms[0]:'all');st.view='workbench';st.stage='brief';}
function destinationPending(){return s.destinationChoice==='existing'&&(!groupMode()||s.destinationCandidate!==s.parentCampaign.key);}
function newCampaignInput(){return JSON.parse(JSON.stringify({activity:s.activity,objective:s.objective,country:s.country,language:s.language,platforms:s.platforms,budgets:s.budgets,groupName:s.groupName,utmPlatform:s.utmPlatform}));}
function resetDestinationWork(){if(['partial','recovered'].includes(s.execution))archiveRun();s.generated=false;s.review=null;s.ready=false;s.preflightFingerprint='';s.codePreview=false;s.enableIntent=null;s.copyDrafts={};s.strategyDrafts={};s.iteration=false;s.iterationBase=null;s.round=1;s.reportKey='current';s.draftCreator=s.currentUser;}
function parentUnavailable(p){if(!p?.id||!p?.accountId)return '尚无已核对的平台计划 ID';if(!['running','paused'].includes(p.status))return '当前计划状态不能新增组';if(p.type==='Performance Max')return '需使用素材资源组流程';if(!p.type||p.type==='类型待核对')return '广告类型待核对';if(!['campaign','group'].includes(p.budgetMode)||!Number.isFinite(Number(p.budget))||Number(p.budget)<=0)return '预算层级或金额待核对';if(!p.objective||p.objective==='未知'||!p.country||p.country==='未知'||!p.language||p.language==='未知')return '父计划配置待核对';return '';}
function chooseCreationMode(choice){
 if(choice==='existing'){s.destinationChoice='existing';s.destinationCandidate=groupMode()?s.parentCampaign.key:'';s.destinationPlatform=groupMode()?s.parentCampaign.platform:(s.platforms.length===1?s.platforms[0]:'all');notice('从广告计划库选择并确认父计划后，再填写新增广告组需求；当前素材与缓存保留。');return;}
 if(s.operation==='new-group'){resetDestinationWork();const draft=s.newCampaignDraft||{activity:initial.activity,objective:initial.objective,country:initial.country,language:initial.language,platforms:initial.platforms.slice(),budgets:{...initial.budgets},groupName:'创意测试组',utmPlatform:'Google'};Object.assign(s,JSON.parse(JSON.stringify(draft)));s.operation='new-campaign';s.parentCampaign=null;}
 s.destinationChoice='new';s.destinationCandidate='';s.view='workbench';s.stage='brief';notice('本次新建广告计划；保留已选素材、缓存和人群需求，已有计划不受影响。');
}
function selectParentCampaign(key,force=false){
 const p=campaignRows().find(r=>r.key===key),reason=parentUnavailable(p);if(reason){notice('暂不能使用此计划：'+reason+'。');return false;}
 if(!force&&groupMode()&&s.parentCampaign.key===key){s.destinationChoice='existing';s.destinationCandidate=key;notice('当前草案已使用这个父计划。');return true;}
 const {groups,...fixed}=p;if(s.operation==='new-campaign')s.newCampaignDraft=newCampaignInput();resetDestinationWork();s.operation='new-group';s.parentCampaign=JSON.parse(JSON.stringify(fixed));s.selectedCampaignKey=p.key;s.destinationChoice='existing';s.destinationCandidate=p.key;s.destinationPlatform=p.platform;s.platforms=[p.platform];s.utmPlatform=p.platform;s.objective=p.objective;s.country=p.country;s.language=p.language;s.activity=p.name;s.groupName='新增创意测试组';s.budgets[p.platform]=Number(p.budget);s.view='workbench';s.stage='brief';notice('已确认父计划 '+p.id+'；本任务仅新增组和暂停广告，素材选版与本机缓存保留。');return true;
}
function destinationSelector(){
 const existing=s.destinationChoice==='existing',rows=campaignRows().filter(r=>s.destinationPlatform==='all'||r.platform===s.destinationPlatform),candidate=rows.find(r=>r.key===s.destinationCandidate),reason=parentUnavailable(candidate),applied=groupMode()&&s.parentCampaign.key===s.destinationCandidate;
 return `<section class="gc-box"><h2>本次广告搭建到哪里？</h2><div class="gc-radiogroup"><label class="gc-radio"><input type="radio" name="gc-destination" value="new" ${!existing?'checked':''}><span>新建广告计划<br><span class="gc-muted">选择一个或多个平台，新建计划、组与广告</span></span></label><label class="gc-radio"><input type="radio" name="gc-destination" value="existing" ${existing?'checked':''}><span>在已有计划下新增广告组<br><span class="gc-muted">从计划库选择一个父计划，沿用平台与账户</span></span></label></div>${existing?`<div class="gc-form" style="margin-top:14px"><label class="gc-label">匹配计划库的平台<select class="gc-select" data-destination-platform>${['all','Google','Meta','TikTok'].map(p=>`<option value="${p}" ${s.destinationPlatform===p?'selected':''}>${p==='all'?'全部平台':p}</option>`).join('')}</select></label><label class="gc-label">选择已有广告计划<select class="gc-select" data-destination-candidate><option value="">请选择父计划</option>${rows.map(r=>{const unavailable=parentUnavailable(r);return `<option value="${r.key}" ${r.key===s.destinationCandidate?'selected':''} ${unavailable?'disabled':''}>${esc(r.platform+' · '+r.name+' · '+(unavailable?unavailable:campaignStatus[r.status]))}</option>`;}).join('')}</select></label></div>${candidate?`<div class="gc-note">${esc(candidate.platform)} · ${esc(candidate.type)} · 目标 ${esc(candidate.objective)} · ${esc(campaignStatus[candidate.status]||'待核对')}</div><div class="gc-key">账户：${esc(candidate.accountId)}<br>父计划 ID：${esc(candidate.id||'待核对')}</div><div class="gc-note">${candidate.budgetMode==='campaign'?'沿用父计划日预算 USD '+candidate.budget+'；本次不能提高父计划预算。':'新组采用独立日预算，默认 USD '+candidate.budget+'，在下方调整并重新审核。'} ${candidate.status==='paused'?'父计划当前暂停；新建子组不会自动启用父计划。':''}</div>`:'<div class="gc-note">计划来自同一个广告计划库；草稿、已结束、配置待核对和本版不支持的类型不能作为普通广告组父计划。</div>'}<div class="gc-row">${btn(applied?'已使用此父计划':'使用此计划新增广告组','destination-apply',true,reason||applied?'disabled':'')}${btn('查看广告计划库','to-campaigns')}</div><div class="gc-note">${destinationPending()?'候选尚未确认：当前不能生成、审核或执行新方案。':'已锁定账户、平台与目标；后续审核和执行沿用这个父计划。'} 计划均为本地示例，真实账户与最新状态尚未同步。</div>`:'<div class="gc-note">在下方填写新计划需求；各选中平台分别创建计划。当前素材、明确版本和本机缓存继续使用。</div>'}</section>`;
}
root.addEventListener('change',e=>{const el=e.target;if(el.name==='gc-destination'){chooseCreationMode(el.value);render();persist();}if(el.hasAttribute('data-destination-platform')){s.destinationPlatform=el.value;s.destinationCandidate=groupMode()&&(el.value==='all'||s.parentCampaign.platform===el.value)?s.parentCampaign.key:'';render();persist();}if(el.hasAttribute('data-destination-candidate')){s.destinationCandidate=el.value;render();persist();}});
function assetCatalog(){return [
 {id:'SUP-001',source:'supplier',name:'角色海报 · 竖版',kind:'image',format:'1080 × 1920 · JPG',versions:s.assetSyncCount?[1,2]:[1],owner:'供应商',sourceUrl:sourceUrls.supplier},
 {id:'SUP-002',source:'supplier',name:'图片转 3D · 演示视频',kind:'video',format:'1080 × 1920 · 15 秒 · MP4',versions:[1],owner:'供应商',sourceUrl:sourceUrls.supplier},
 {id:'CRE-001',source:'creator',name:'达人 A · 角色创作演示',kind:'video',format:'1080 × 1920 · 22 秒 · MP4',versions:[1],owner:'达人 A',sourceUrl:sourceUrls.creator},
 {id:'MAN-001',source:'manual',name:'产品演示 · 本机登记',kind:'video',format:'1920 × 1080 · MP4',versions:Array.from({length:s.manualCatalogVersion},(_,i)=>i+1),owner:'Alex',sourceUrl:''},
 ...(s.assetSyncCount?[{id:'SUP-003',source:'supplier',name:'角色细节 · 新入库图片',kind:'image',format:'1080 × 1080 · PNG',versions:[1],owner:'供应商',sourceUrl:sourceUrls.supplier}]:[])
 ];}
function resolveAsset(key){const [id,v]=String(key).split('@'),version=Number(v),a=assetCatalog().find(x=>x.id===id);if(!a||!a.versions.includes(version))return null;const manual=id==='MAN-001',mime=manual?s.manualVersionMimes[version]||'video/mp4':null;return {...a,key,version,hash:'DEMO-'+id+'-v'+version,name:manual?(s.manualVersionNames[version]||'产品演示-v'+version+'.mp4'):a.name,filename:manual?(s.manualVersionNames[version]||'产品演示-v'+version+'.mp4'):id+'-v'+version+(a.kind==='video'?'.mp4':a.format.includes('PNG')?'.png':'.jpg'),kind:manual?(mime.startsWith('image/')?'image':'video'):a.kind,format:manual?(mime+' · 本机登记'):a.format,owner:manual?(s.manualVersionOwners[version]||'Alex'):a.owner,originMachine:manual?(s.manualVersionMachines[version]||'alex-main'):null,rightsVersion:1,analysisVersion:1,captionVersion:1,method:a.source==='creator'&&s.creatorMode==='post'?'post':'file'};}
function selectedAssets(){return s.picked.map(resolveAsset).filter(Boolean);}
function registerManual(name,mime){if(!machineOwned()){notice('请先选择当前登记者自己的演示电脑，再登记本机文件。');return;}s.manualCatalogVersion++;const version=s.manualCatalogVersion;s.manualVersionNames[version]=name;s.manualVersionMachines[version]=s.assetMachine;s.manualVersionOwners[version]=s.currentUser;s.manualVersionMimes[version]=mime||'video/mp4';s.uploadName=name;s.uploadMime=mime;s.uploadVersion=version;s.picked=[...s.picked.filter(k=>!k.startsWith('MAN-001@')),'MAN-001@'+version];s.assetBrowseVersions['MAN-001']=version;notice('已登记并选用本机文件 v'+version+'；仅记录名称与类型，未读取或上传文件。请先完成素材准备。');}
function manualSelectionShared(){const list=selectedAssets().filter(a=>a.source==='manual');return list.length>0&&list.every(a=>s.manualSharedVersions[a.version]);}
function canShareManual(){const list=selectedAssets().filter(a=>a.source==='manual');return list.length>0&&machineOwned()&&list.every(a=>a.owner===s.currentUser&&a.originMachine===s.assetMachine);}
function hasSource(source){return selectedAssets().some(a=>a.source===source);}
function postCaption(){return selectedAssets().filter(a=>a.method==='post').map(a=>s.assetAnalysis[a.key]?.caption||'').filter(Boolean).join('\n');}
function assetIdentity(){return selectedAssets().map(a=>({key:a.key,hash:a.hash,method:a.method,rightsVersion:a.rightsVersion,analysisVersion:a.analysisVersion,captionVersion:a.captionVersion,caption:a.method==='post'?(s.assetAnalysis[a.key]?.caption||null):null})).sort((a,b)=>a.key.localeCompare(b.key));}
function assetManifest(){return selectedAssets().map(a=>({key:a.key,id:a.id,version:a.version,name:a.name,filename:a.filename,source:a.source,sourceUrl:a.sourceUrl,kind:a.kind,hash:a.hash,method:a.method,rightsVersion:a.rightsVersion,analysisVersion:a.analysisVersion,captionVersion:a.captionVersion,caption:a.method==='post'?(s.assetAnalysis[a.key]?.caption||''):null,platforms:a.method==='post'?['TikTok']:['Google','Meta','TikTok']}));}
function cacheOf(a){return s.assetCache[s.assetMachine]?.[a.key];}
function cached(a){const c=cacheOf(a);return c?.status==='ready'&&c.hash===a.hash;}
function machineOwned(){return machines[s.assetMachine]?.owner===s.currentUser;}
function executionFingerprint(){return stateKey([fingerprint(),s.assetMachine,s.currentUser]);}
function assetErrors(stage='generation'){
 const errors=[];if(!s.picked.length)errors.push('请先从素材库选择具体文件和版本');
 if(s.picked.some(key=>!resolveAsset(key)))errors.push('所选素材版本无法解析，请重新明确文件版本');
 selectedAssets().forEach(a=>{if(!s.assetAnalysis[a.key]||s.assetAnalysis[a.key].hash!==a.hash)errors.push(a.id+' v'+a.version+' 尚未完成内容与授权检查');if(a.method==='post'){if(!s.assetAnalysis[a.key]?.caption)errors.push(a.id+' 原帖文案与授权引用待检查');}else if(stage!=='review'&&!cached(a))errors.push(a.id+' v'+a.version+' 在当前电脑缺失或未通过校验');});
 if(stage!=='review'&&!machineOwned())errors.push('请切换到当前执行者自己的演示电脑');
 return errors;
}
function assetLog(message){s.assetTransferLog=[...s.assetTransferLog,message].slice(-5);}
function prepareAssets(checkOnly=false){
 if(!machineOwned()){notice('演示身份与电脑所有者不同，请选择自己的电脑后再检查或获取素材。');return;}
 const store=s.assetCache[s.assetMachine]||(s.assetCache[s.assetMachine]={});let reused=0,downloaded=0,failed=0,posts=0,local=0;
 selectedAssets().forEach(a=>{
  if(a.method==='post'){if(!checkOnly){s.assetAnalysis[a.key]={hash:a.hash,caption:'Watch this character go from a reference image to a 3D preview.',rightsVersion:1};posts++;}return;}
  if(cached(a)){reused++;if(!checkOnly)s.assetAnalysis[a.key]={hash:a.hash,rightsVersion:1};return;}
  if(checkOnly)return;
  if(a.key===s.assetFailureRef){store[a.key]={...store[a.key],status:'failed',error:'共享文档附件下载权限不足 · 示例'};failed++;return;}
  if(a.source==='manual'&&s.assetMachine!==a.originMachine&&!s.manualSharedVersions[a.version]){store[a.key]={...store[a.key],status:'failed',error:'文件仅在登记电脑；需补充该版本的共享来源'};failed++;return;}
  const isLocal=a.source==='manual'&&s.assetMachine===a.originMachine;
  store[a.key]={status:'ready',hash:a.hash,fetches:(store[a.key]?.fetches||0)+(isLocal?0:1),method:isLocal?'本机登记示例':'共享文档获取示例'};s.assetAnalysis[a.key]={hash:a.hash,rightsVersion:1};if(isLocal)local++;else downloaded++;
 });
 const result=checkOnly?'缓存检查：命中 '+reused+' 个；缺失 '+selectedAssets().filter(a=>a.method==='file'&&!cached(a)).length+' 个；没有下载。':'准备结果：复用 '+reused+' 个，新获取 '+downloaded+' 个，本机登记 '+local+' 个，原帖核对 '+posts+' 个，失败 '+failed+' 个。';
 assetLog(machines[s.assetMachine].name+'：'+result);notice(result+' 本地演示，未读取或下载真实文件。');
}
function materialTable(list=assetManifest(),frozen=false){return `<div class="gc-tablewrap"><table><thead><tr><th>具体素材 / 版本</th><th>用途 / 来源</th><th>${frozen?'审核内容标识':'当前电脑状态'}</th></tr></thead><tbody>${list.map(a=>{const full=resolveAsset(a.key),c=full?cacheOf(full):null;return `<tr><td>${esc(a.name)}<br><span class="gc-key">${a.id} · v${a.version}</span></td><td>${a.method==='post'?'TikTok 原帖授权引用':'文件 / '+({supplier:'供应商',creator:'达人',manual:'本机登记'})[a.source]}</td><td>${frozen?'<span class="gc-key">'+esc(a.hash)+'</span>':a.method==='post'?chip(s.assetAnalysis[a.key]?.caption?'原帖引用已核对 · 示例':'原帖引用待检查',s.assetAnalysis[a.key]?.caption?'good':'pending'):chip(full&&cached(full)?'本机可复用':c?.status==='failed'?'获取失败':'本机缺失',full&&cached(full)?'good':c?.status==='failed'?'fail':'pending')}${!frozen&&c?.error?'<div class="gc-note">'+esc(c.error)+'</div>':''}${!frozen&&c?.fetches?'<div class="gc-note">本机获取次数：'+c.fetches+'</div>':''}${!frozen&&full&&full.method==='file'&&cached(full)?btn('模拟本机文件丢失','asset-evict',false,'data-asset-key="'+a.key+'"'):''}</td></tr>`;}).join('')||'<tr><td colspan="3">尚未选择具体素材</td></tr>'}</tbody></table></div>`;}
function preparationPanel(compact=false){const ready=!assetErrors('generation').length;return `<section class="gc-box"><div class="gc-spread"><h2>${compact?'本次选材与本机准备':'素材准备 · 先检查文件，再生成方案'}</h2>${chip(ready?'演示：素材已就绪':'素材待准备',ready?'good':'pending')}</div><div class="gc-note">当前执行环境：${esc(s.currentUser)} / ${esc(machines[s.assetMachine]?.name)} · 云盘尚未接入</div>${materialTable()}<div class="gc-note">目录与选版可共享；缓存按电脑分别检查。同一版本命中缓存时直接复用。所有文件指纹、预览与检查结果均为示例。</div><div class="gc-form"><label class="gc-label">获取失败分支<select class="gc-select" data-asset-failure><option value="">正常获取</option>${selectedAssets().filter(a=>a.method==='file').map(a=>`<option value="${a.key}" ${s.assetFailureRef===a.key?'selected':''}>${a.id} v${a.version} · 模拟无下载权限</option>`).join('')}</select></label><div class="gc-row">${btn('检查这台电脑的素材（演示）','asset-check')}${btn('补齐缺少的素材（演示）','asset-prepare',true,s.picked.length?'':'disabled')}</div></div>${s.assetTransferLog.length?'<div class="gc-log">'+s.assetTransferLog.slice(-3).map(x=>'<div>'+esc(x)+'</div>').join('')+'</div>':''}${!compact&&assetErrors('generation').length?'<div class="gc-notice" role="alert">'+assetErrors('generation').map(esc).join('；')+'</div>':''}</section>`;}
function preparation(){return preparationPanel()+`<div class="gc-foot">${btn('返回选择素材','to-assets')}${btn('生成投放方案示例 →','generate',true)}</div>`+codex('按素材 ID 与版本检查当前电脑缓存；缺失才获取，单项失败仅补失败项。素材检查完成后生成方案，审核锁定素材清单。');}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(!['asset-select','asset-remove','asset-check','asset-prepare','asset-share','asset-evict'].includes(a))return;
 if(a==='asset-select'){const item=resolveAsset(b.dataset.assetKey);if(item){s.picked=[...s.picked.filter(k=>!k.startsWith(item.id+'@')),item.key];notice('本次明确选用 '+item.id+' v'+item.version+'；生成、审核与执行都绑定这个版本。');}}
 if(a==='asset-remove'){s.picked=s.picked.filter(k=>!k.startsWith(b.dataset.assetId+'@'));notice('已从本次计划移除该素材；共享目录和本机缓存继续保留。');}
 if(a==='asset-evict'){const key=b.dataset.assetKey,store=s.assetCache[s.assetMachine]||(s.assetCache[s.assetMachine]={});store[key]={...store[key],status:'missing',error:''};s.ready=false;notice('仅模拟当前电脑该版本文件丢失；选材与原审核保持。获取缺失项后重新预检即可。');}
 if(a==='asset-check')prepareAssets(true);
 if(a==='asset-prepare')prepareAssets(false);
 if(a==='asset-share'&&!canShareManual()){notice('请由所选本机版本的登记者，在登记电脑补充共享来源；当前电脑无法代取原文件。');render();persist();return;}
 if(a==='asset-share'){selectedAssets().filter(a=>a.source==='manual').forEach(a=>s.manualSharedVersions[a.version]=true);notice('已模拟补充本机素材的共享文档共享来源；没有真实上传或修改共享文档。其他电脑可演示获取缺失项。');}
 render();persist();
});
root.addEventListener('change',e=>{const el=e.target;if(el.dataset.assetVersion){s.assetBrowseVersions[el.dataset.assetVersion]=Number(el.value);render();persist();}if(el.hasAttribute('data-asset-machine')){s.assetMachine=el.value;s.ready=false;notice('已切换演示电脑；选材和审核保持，需核对该电脑缓存并重新预检。');render();persist();}if(el.hasAttribute('data-asset-failure')){s.assetFailureRef=el.value;render();persist();}});
function groupLabel(platform){return platform==='Meta'?'广告组 / Ad Set':'广告组 / Ad Group';}
function groupMode(){return s.operation==='new-group'&&!!s.parentCampaign;}
function targetKey(){return [s.operation,s.parentCampaign?.key||null,s.groupName,selectedAssets().filter(a=>a.method==='post').map(a=>[a.key,s.assetAnalysis[a.key]?.caption||null])];}
function stateKey(value){const text=JSON.stringify(value);let key=2166136261;for(let i=0;i<text.length;i++)key=Math.imul(key^text.charCodeAt(i),16777619);return (key>>>0).toString(36);}
function canReview(){return s.currentUser==='Alex';}
function approved(){return v2TrackingReady()&&!destinationPending()&&!!(s.generated&&s.review&&s.review.fingerprint===fingerprint());}
function suggestedCopy(p){const c=copy[p],base=s.iterationBase;if(!s.iteration||base?.platform!==p)return c;const variants={Google:['Explore Your Character in 3D','Give Your Sketch a New Shape'],Meta:['A new way to build your character.','Your reference. Your next creation.'],TikTok:['See your reference take a new shape','Watch this sketch become a 3D idea']};const titles=variants[p];let title=titles[(s.round-2)%titles.length];if(title===base.title)title=titles[(s.round-1)%titles.length];return {...c,title,body:base.body};}
function effectiveCopy(p){const c=suggestedCopy(p);const locked=p==='TikTok'&&hasSource('creator')&&s.creatorMode==='post';return {title:locked?(postCaption()||''):(s.copyDrafts[p]?.title??c.title),body:locked?(postCaption()||''):(s.copyDrafts[p]?.body??c.body)};}
function effectiveStrategy(p){const strategy=p==='Google'?'以图片转 3D 的明确搜索意图为假设，按主题拆分广告组，避免无关流量。':p==='Meta'?'以角色创作前后对比测试创意，分别验证人群假设和文案；保持测试变量可区分。':'用前几秒展示输入图片与生成结果，检验开头和 CTA；先验证素材及落地页一致性。';return {strategy,...(p==='Google'?{keywords:'image to 3d\ncharacter to 3d\nai 3d model generator',negative:'jobs\ntraining course'}:{}),...s.strategyDrafts[p]};}
function reportRuns(){const current={key:'current',version:s.version,objects:s.runObjects,snapshot:s.runSnapshot,execution:s.execution};return [current,...s.runHistory.slice().reverse().map(h=>({...h,key:'run-'+h.version}))];}
function selectedReport(){return reportRuns().find(r=>r.key===s.reportKey)||reportRuns()[0];}
function reportData(run){return s.simulatedReports['V'+run.version]||null;}
function iterationParent(run,p){const obj=run.objects?.[p];return obj?campaignRows().find(r=>r.platform===p&&r.id===obj.campaignId):null;}
function startCampaign(blank=false){archiveRun();v2ResetWork(blank);s.operation='new-campaign';s.parentCampaign=null;s.destinationChoice='new';s.destinationCandidate='';s.newCampaignDraft=null;s.groupName='创意测试组';s.draftCreator=s.currentUser;s.activity=blank?'':s.activity+' · 副本';s.generated=false;s.review=null;s.copyDrafts={};s.strategyDrafts={};s.iteration=false;s.iterationBase=null;s.round=1;s.enableIntent=null;s.reportKey='current';s.originalPostExample='';if(blank){s.picked=[];s.platforms=[];s.audience='';s.audienceEnabled=false;s.audienceBinding=null;s.landingMode='activity';s.landing='';}s.view='workbench';s.stage='brief';notice(blank?'已建立空白计划草案，请明确平台、素材、目标与落地页。':'已复制为新计划草案，需重新生成和审核。');}
function startIteration(){const run=selectedReport(),p=s.iterationPlatform,parent=iterationParent(run,p),data=reportData(run),plan=run.snapshot?.plan,obj=run.objects?.[p];if(!parent||!data?.metrics[p]||!plan?.assetManifest?.length||!obj||s.iterationAction!=='new-group'||!s.iterationAcknowledged){notice('请先明确已有对象、日报数据、冻结的具体素材、下一轮动作和预算影响。');return;}const base=plan.outputs[p],round=(plan.round||1)+1;if(s.operation==='new-campaign')s.newCampaignDraft=newCampaignInput();archiveRun();const {groups,...fixed}=parent;s.operation='new-group';s.parentCampaign=fixed;s.destinationChoice='existing';s.destinationCandidate=parent.key;s.destinationPlatform=parent.platform;s.selectedCampaignKey=parent.key;s.platforms=[p];s.utmPlatform=p;s.activity=parent.name;s.groupName=(obj.groupName||'创意测试组')+' · 对照 V'+s.version;s.country=parent.country;s.language=parent.language;s.objective=parent.objective;s.budgets[p]=parent.budgetMode==='campaign'?Number(parent.budget):Number(plan.budgets[p]);s.picked=plan.assetManifest.map(a=>a.key);s.creatorMode=plan.creatorMode;s.uploadName=plan.uploadName||'';s.uploadMime=plan.uploadMime||'';s.uploadVersion=plan.uploadVersion||0;s.audience=plan.audience;s.audienceEnabled=!!plan.audienceBinding;s.audienceBinding=plan.audienceBinding?JSON.parse(JSON.stringify(plan.audienceBinding)):null;s.audienceTest=plan.audienceTest;s.landingMode=plan.landingMode;s.landing=plan.landing;s.iterationBase={platform:p,version:run.version,groupId:obj.groupId,title:base.title,body:base.body,strategy:base.strategy};s.iteration=true;s.round=round;s.draftCreator=s.currentUser;s.generated=false;s.review=null;s.copyDrafts={};s.strategyDrafts={};s.iterationAcknowledged=false;s.iterationAction='';s.reportKey='current';v2RestoreTracking(plan,p);s.view='workbench';s.stage='brief';task('下一轮草案：复用父计划 '+parent.id+'，新增 '+s.groupName+'；来源组 '+obj.groupId+'；等待重新审核');notice('已建立明确的独立测试组草案；原组保留，父计划 ID 复用，尚未执行。');}
function findPlan(key){return [s.runSnapshot,...s.runHistory.map(h=>h.snapshot)].map(x=>x?.plan).find(p=>p?.key===key);}
function auditView(){const p=findPlan(s.selectedPlanKey);if(!p)return pagehead('AUDIT / 审核快照','当前记录缺少完整审核快照','旧版示例不补造审核内容。',btn('返回计划台账','to-campaigns'));return pagehead('AUDIT / V'+p.version,p.activity,'此处显示执行时固定的审核内容，后续草案修改不会覆盖。',btn('返回计划台账','to-campaigns'))+`<section class="gc-box"><div class="gc-note">审核人：${esc(p.review.reviewer)} · 版本 V${p.version} · 指纹 ${p.key}</div><div class="gc-note">${p.country} / ${p.language} · 目标 ${p.objective} · 父计划 ${p.parent?.id||'本版新建'}</div><div class="gc-key">${esc(p.finalLanding||p.landing)}</div></section>${p.assetManifest?'<section class="gc-box"><h2>执行时冻结的素材清单</h2>'+materialTable(p.assetManifest,true)+'</section>':'<div class="gc-note">旧版示例没有具体文件清单，保留原记录。</div>'}${Object.entries(p.outputs).map(([platform,o])=>`<section class="gc-box"><h2>${platform}</h2><div class="gc-note">标题／原帖文案：${esc(o.title)}</div><div class="gc-note">正文：${esc(o.body)}</div><div class="gc-note">策略：${esc(o.strategy.strategy)}</div>${o.strategy.keywords!==undefined?'<div class="gc-note">关键词：'+esc(o.strategy.keywords)+'</div>':''}${o.strategy.negative!==undefined?'<div class="gc-note">否定关键词：'+esc(o.strategy.negative)+'</div>':''}<div class="gc-note">素材用途：${esc(o.assetUse.role)} · ${o.assetUse.ids.join('、')}</div></section>`).join('')}`;}
function assetUse(p){const all=selectedAssets();if(p==='Google')return {ids:all.map(a=>a.key),role:'仅作创意参考',note:'本版 Search 使用文字与关键词，不上传图片、视频或原帖。'};if(p==='TikTok'&&all.some(a=>a.method==='post'))return {ids:all.filter(a=>a.method==='post').map(a=>a.key),role:'TikTok 授权原帖',note:'本方案使用选定的原帖版本与 caption；其余文件不在此平台上传。'};const list=all.filter(a=>a.method==='file'&&(p==='Meta'||a.kind==='video'));return {ids:list.map(a=>a.key),role:'指定版本的投放文件',note:p==='TikTok'?'只使用此处列出的选定视频版本。':'只使用此处列出的图片或视频版本；使用范围需在真实接入时核对。'};}
function capturePlan(){return JSON.parse(JSON.stringify({key:fingerprint(),version:s.version,round:s.round,activity:s.activity,operation:s.operation,parent:s.parentCampaign,groupName:s.groupName,platforms:s.platforms,budgets:s.budgets,country:s.country,language:s.language,objective:s.objective,picked:s.picked,creatorMode:s.creatorMode,uploadName:s.uploadName,uploadMime:s.uploadMime,uploadVersion:s.uploadVersion,audience:s.audience,audienceBinding:s.audienceEnabled?s.audienceBinding:null,audienceTest:s.audienceTest,assetManifest:assetManifest(),tracking:v2TrackingSnapshot(),startAt:s.startAt,timeZone:s.timeZone,landingMode:s.landingMode,landing:s.landing,finalLanding:s.landingMode==='activity'?s.landing:'https://example.com/features/ai-3d-model-generator',outputs:Object.fromEntries(s.platforms.map(p=>[p,{...effectiveCopy(p),strategy:effectiveStrategy(p),assetUse:assetUse(p)}])),review:{...s.review}}));}
function audienceSnapshot(){return {definition:s.audienceDefinition,version:s.audienceVersion,purpose:s.audiencePurpose,stage:s.audienceStage,derivedReady:s.audienceDerivedReady,platforms:s.audienceSyncedPlatforms.slice(),confirmed:s.audienceDefinitionConfirmed,refund:s.audienceRefund,window:s.audienceWindow,source:s.audienceSource};}
if(s.audienceEnabled&&!s.audienceBinding)s.audienceBinding=audienceSnapshot();
function bindingLabel(){const b=s.audienceBinding;return b?(b.catalogName||populationNames[b.definition]||b.definition)+' · v'+b.version+' · '+purposeNames[b.purpose]:'尚未绑定人群包';}
function generationFingerprint(){return stateKey([v2TrackingSignature(true),targetKey(),assetIdentity(),s.creatorMode,s.activity,s.audience,s.country,s.language,s.objective,s.platforms,s.landingMode,s.landing,s.audienceEnabled?s.audienceBinding:null,s.iteration]);}
function fingerprint(){return stateKey([v2TrackingSignature(),s.startAt,s.timeZone,targetKey(),assetIdentity(),s.creatorMode,s.activity,s.audience,s.country,s.language,s.objective,s.platforms,s.budgets,s.landingMode,s.landing,s.copyDrafts,s.strategyDrafts,s.audienceTest,s.audienceEnabled?s.audienceBinding:null]);}
function archiveRun(){if(['partial','recovered'].includes(s.execution)){s.runHistory=[...s.runHistory,{version:s.version,result:s.execution,platforms:(s.resultPlatforms||s.platforms).slice(),ids:{...s.runIds},objects:{...s.runObjects},snapshot:s.runSnapshot||null,executors:{...s.runExecutors}}];}v2ResetWork();s.execution='idle';s.ready=false;s.codePreview=false;s.resultFingerprint='';s.runIds={};s.runObjects={};s.runExecutors={};s.runSnapshot=null;s.enableIntent=null;s.version++;}
function checkRevision(){if(s.generated&&s.generationFingerprint!==generationFingerprint())s.generated=false;const fp=fingerprint();if(s.review&&s.review.fingerprint!==fp)s.review=null;if(s.ready&&(s.preflightFingerprint!==executionFingerprint()||!approved()||assetErrors('execution').length))s.ready=false;if(['partial','recovered'].includes(s.execution)&&s.resultFingerprint&&s.resultFingerprint!==fp)archiveRun();}
function recordRunObject(p){const parent=groupMode()?s.parentCampaign:null;const obj={platform:p,accountId:parent?.accountId||'DEMO-'+p[0]+'-ACCOUNT',campaignId:parent?.id||'DEMO-'+p[0]+'-CAM-V'+s.version,groupId:'DEMO-'+p[0]+'-'+(p==='Meta'?'SET':'GROUP')+'-V'+s.version,adId:s.runIds[p],groupName:s.groupName,creator:s.draftCreator,executor:s.currentUser,reviewer:s.review?.reviewer||'未知',parentKey:parent?.key||p+':DEMO-'+p[0]+'-CAM-V'+s.version,status:'paused',budget:s.budgets[p],assetRefs:assetUse(p).ids.slice(),planKey:s.runSnapshot?.plan?.key||fingerprint(),version:s.version};s.runObjects[p]=obj;v2TrackingBackfill(p,obj);if(parent&&!s.extraGroups.some(g=>g.groupId===obj.groupId))s.extraGroups=[...s.extraGroups,obj];}
function setRun(result){s.failedPlatform=s.platforms.includes('TikTok')?'TikTok':s.platforms[s.platforms.length-1];s.execution=result;s.resultPlatforms=s.platforms.slice();s.runSnapshot={plan:capturePlan(),activity:s.activity,creator:s.draftCreator,reviewer:s.review?.reviewer||'未知',budgets:{...s.budgets},operation:s.operation,parent:s.parentCampaign,groupName:s.groupName,startedBy:s.currentUser,country:s.country,language:s.language,objective:s.objective,types:Object.fromEntries(s.platforms.map(p=>[p,groupMode()?s.parentCampaign.type:p==='Google'?'Search':p==='Meta'?'网站转化':'Website conversions'])),budgetModes:Object.fromEntries(s.platforms.map(p=>[p,groupMode()?s.parentCampaign.budgetMode:p==='TikTok'?'group':'campaign']))};s.runIds=Object.fromEntries(s.platforms.filter(p=>result!=='partial'||p!==s.failedPlatform).map(p=>[p,'DEMO-'+p[0]+'-V'+s.version+'-001']));s.runExecutors=Object.fromEntries(Object.keys(s.runIds).map(p=>[p,s.currentUser]));s.runObjects={};Object.keys(s.runIds).forEach(recordRunObject);s.resultFingerprint=fingerprint();s.preflightFingerprint=executionFingerprint();s.ready=true;}
function localErrors(execution=false,materialStage){const errors=assetErrors(materialStage||(execution?'execution':'generation'));if((execution||materialStage==='review')&&!v2TrackingReady())errors.push('请先确认落地页并生成本版追踪链接');if(destinationPending())errors.unshift('请先在投放需求确认已有父计划，或切回新建广告计划');s.platforms.forEach(p=>{const use=assetUse(p);if(p!=='Google'&&!use.ids.length)errors.push(p+' 尚无可用于本版方案的投放素材；原帖授权只用于对应平台');if(s.generated){const out=effectiveCopy(p);if(!out.title.trim())errors.push(p+' 标题／原帖文案不能为空');if(!out.body.trim())errors.push(p+' 正文不能为空');if(p==='Google'&&!(s.strategyDrafts.Google?.keywords??'image to 3d').trim())errors.push('Google 搜索关键词不能为空');}});if(s.operation==='new-group'){const p=s.parentCampaign;if(!p?.id||!p?.accountId)errors.push('需明确已有平台账户和父计划 ID');if(!s.groupName.trim())errors.push('请填写广告组名称');if(p&&(!['running','paused'].includes(p.status)||p.type==='Performance Max'))errors.push('此父计划状态或类型不能使用当前新增广告组流程');if(p&&(s.platforms.length!==1||s.platforms[0]!==p.platform||s.objective!==p.objective))errors.push('新增组的平台与目标必须和父计划一致');if(p?.budgetMode==='campaign'&&Number(s.budgets[p.platform])!==Number(p.budget))errors.push('本次仅新增广告组，不能改动父计划预算');if(p?.platform==='Google'&&(s.country!==p.country||s.language!==p.language))errors.push('Google 此类型的地区和语言沿用父计划');}if(!s.picked.length)errors.push('请选择素材');if(!s.platforms.length)errors.push('请选择投放平台');s.platforms.forEach(p=>{if(!Number.isFinite(Number(s.budgets[p]))||Number(s.budgets[p])<=0)errors.push(p+' 每日预算需大于 0，或取消该平台');});if(!s.activity.trim())errors.push('请填写活动名称');if(!s.audience.trim())errors.push('请填写人群方向');if(!s.country.trim())errors.push('请填写投放地区');if(!/^[A-Za-z0-9_-]{1,64}$/.test(s.audienceTest))errors.push('测试标签仅使用 1–64 位字母、数字、下划线或短横线');if(execution||materialStage==='review')try{const u=new URL(s.landingMode==='activity'?s.landing:'https://example.com/features/ai-3d-model-generator');if(!['https:','http:'].includes(u.protocol))throw Error();}catch(_){errors.push('落地页 URL 无效，请先修正');}if(execution&&!s.generated)errors.push('请先在投放需求中生成方案预览');if(execution&&!approved())errors.push('当前方案尚未完成人工审核，请到第 5 步审核投放方案');if(execution&&s.objective==='Payment')errors.push('付费转化事件与业务口径尚未确认');if(execution&&s.audienceEnabled&&!s.platforms.every(audienceReady))errors.push('已绑定的人群版本尚未可用于所有选中平台；请处理后重新绑定，或显式解除绑定');return errors;}
function applyCopyDrafts(){root.querySelectorAll('input[data-copy]').forEach(el=>{if(el.readOnly)return;const p=el.dataset.copy,body=el.closest('.gc-box').querySelector('[data-copy-body]');el.dataset.copyPart='title';el.value=s.copyDrafts[p]?.title??el.value;if(body){body.dataset.copy=p;body.dataset.copyPart='body';body.value=s.copyDrafts[p]?.body??body.value;}});}

