function paintSaveStatus(){const el=root.querySelector('[data-save-status]');if(!el)return;el.textContent=saveStatusText;el.hidden=!saveStatusText;el.className=saveStatusTone==='warning'?'gc-notice':'gc-note';el.dataset.saveTone=saveStatusTone;el.setAttribute('role',saveStatusTone==='warning'?'alert':'status');}
function updateSaveStatus(text,tone){saveStatusText=text;saveStatusTone=tone;paintSaveStatus();}
function persist(){
 const sequence=++saveSequence;
 const recovery='当前页面内容仍保留；刷新只能回到上次成功保存的快照。正式版需要后端保存完整方案和审核记录。';
 const fail=()=>{if(sequence===saveSequence)updateSaveStatus('保存失败。'+recovery,'warning');};
 try{
  const payload={modelContent:{prototype:'Ad Growth Console 广告增长控制台',page:s.view,stage:s.stage,activity:s.activity,selectedSources:s.picked,creatorMode:s.creatorMode,platforms:s.platforms,landingMode:s.landingMode,executionScenario:s.execution,audiencePackage:s.audienceEnabled?s.audienceBinding:null,taskScope:s.operation,parentCampaign:s.parentCampaign?{platform:s.parentCampaign.platform,id:s.parentCampaign.id}:null,assetRefs:s.picked,executionMachine:s.assetMachine,simulationOnly:true},privateContent:{version:1,writer:writerId,state:{...s,toast:'',promptVisible:false}}};
  const bytes=new TextEncoder().encode(JSON.stringify(payload)).byteLength;
  if(bytes>=16*1024){updateSaveStatus('保存提醒：完整快照已达到本地保存容量（16 KiB），本次未保存。'+recovery,'warning');return Promise.resolve(false);}
  if(!window.demoHost?.setWidgetState){updateSaveStatus('当前浏览器无法保存演示记录；刷新后可能丢失本次修改。','warning');return Promise.resolve(false);}
  updateSaveStatus('正在保存当前完整快照…','pending');
  return Promise.resolve(window.demoHost.setWidgetState(payload)).then(()=>{if(sequence!==saveSequence)return false;confirmedSaveSequence=sequence;updateSaveStatus('演示记录已保存到当前浏览器。','good');return true;},()=>{fail();return false;});
 }catch(_){fail();return Promise.resolve(false);}
}
