function audienceReady(p){if(!s.audienceEnabled)return true;const b=s.audienceBinding;if(!b||!b.confirmed||b.refund==='unconfirmed'||!b.platforms.includes(p))return false;if(b.stage==='usable')return b.purpose!=='seed'||b.derivedReady;if(b.stage==='matching'&&p==='Meta')return b.purpose!=='seed';return false;}
function audienceRows(){return s.platforms.map(p=>{
  if(!s.audienceSyncedPlatforms.includes(p))return[p,'—',s.audienceStage==='draft'?'待定义与校验':'此平台待同步','未知','pending'];
  if(s.audienceStage==='usable')return[p,'DEMO-'+p[0]+(s.audiencePurpose==='seed'&&s.audienceDerivedReady&&p!=='Google'?'-EXP-':'-AUD-')+s.audienceVersion,s.audiencePurpose==='seed'?(s.audienceDerivedReady?(p==='Google'?'信号配置已核对（演示）':'拓展实例可用（演示）'):(p==='Google'?'基础包可用 · 信号待配置':'种子可用 · 拓展待创建')):'可用（演示）','未提供精确人数',s.audiencePurpose==='seed'&&!s.audienceDerivedReady?'pending':'good'];
  if(s.audienceStage==='matching'&&p==='Meta')return[p,'DEMO-M-AUD-'+s.audienceVersion,'可用（演示）','平台未提供精确人数','good'];
  if(s.audienceStage==='matching'&&p==='TikTok')return[p,'DEMO-T-AUD-'+s.audienceVersion,'规模不足（演示）','830 · 示例','pending'];
  if(s.audienceStage==='matching'&&p==='Google')return[p,'DEMO-G-AUD-'+s.audienceVersion,'平台匹配中（演示）','未知','pending'];
  return[p,'—',s.audienceStage==='prepared'?'待提交平台':'待定义与校验','未知','pending'];
});}
