<label class="gc-label">来源<select class="gc-select" data-aud-field="audienceSource"><option value="export" ${s.audienceSource==='export'?'selected':''}>后台导出的受限文件</option><option value="database" ${s.audienceSource==='database'?'selected':''}>数据库规则提取</option></select></label>
